#include "reference/cartesian_reference.cpp"
using Key=uint64_t;using DP=map<Key,int64_t>;uint64_t all_compiled_rules=0;
int imask(Key k){return k>>40&31;}int omask(Key k){return k>>45&31;}int partner(Key k,int i){return (k>>(4*i))&15;}
Key makekey(int in,int out,array<int,10>p){Key k=Key(in)<<40|Key(out)<<45;for(int i=0;i<10;i++)k|=Key(p[i])<<(4*i);return k;}
Key identity(int mask){array<int,10>p;p.fill(15);for(int i=0;i<5;i++)if(mask>>i&1){p[i]=i+5;p[i+5]=i;}return makekey(mask,mask,p);}
void dadd(DP&d,Key k,I c){I value=I(d[k])+c;assert(value>=INT64_MIN&&value<=INT64_MAX);if(value)d[k]=int64_t(value);else d.erase(k);}
vector<pair<Key,int>> elementary(int mask,int letter){int a=rule::aof(letter),b=rule::bof(letter),o=rule::op(letter);bool aa=mask>>a&1,bb=mask>>b&1;vector<pair<Key,int>>v;auto make=[&](int out,vector<pair<int,int>>edges,int c){array<int,10>p;p.fill(15);for(int i=0;i<5;i++)if(i!=a&&i!=b&&(mask>>i&1))p[i]=i+5,p[i+5]=i;for(auto[x,y]:edges)p[x]=y,p[y]=x;v.push_back({makekey(mask,out,p),c});};if(o==0){if(aa&&bb)make(mask^(1<<a)^(1<<b),{{a,b}},1);}else if(o==1){if(!aa&&!bb)make(mask|(1<<a)|(1<<b),{{a+5,b+5}},1);}else if(aa!=bb){if(aa)make(mask^(1<<a)^(1<<b),{{a,b+5}},1);else make(mask^(1<<a)^(1<<b),{{b,a+5}},1);}else if(aa&&bb){make(mask,{{a,b+5},{b,a+5}},1);make(mask,{{a,b},{a+5,b+5}},-1);}return v;}
struct DSU{int p[15];bool active[15]{};DSU(){iota(p,p+15,0);}int root(int i){while(p[i]!=i){p[i]=p[p[i]];i=p[i];}return i;}void join(int a,int b){active[a]=active[b]=true;p[root(a)]=root(b);}};
pair<Key,int64_t> compose(Key first,Key second){assert(omask(first)==imask(second));DSU u;for(int i=0;i<10;i++){int j=partner(first,i);if(j<10&&i<j)u.join(i,j);j=partner(second,i);if(j<10&&i<j)u.join(i+5,j+5);}array<vector<int>,15> ext;for(int i=0;i<5;i++){if(imask(first)>>i&1)ext[u.root(i)].push_back(i);if(omask(second)>>i&1)ext[u.root(i+10)].push_back(i+5);}array<int,10>p;p.fill(15);int64_t factor=1;for(int i=0;i<15;i++)if(u.active[i]&&u.root(i)==i){assert(ext[i].size()==0||ext[i].size()==2);if(ext[i].empty())factor*=3;else{int a=ext[i][0],b=ext[i][1];p[a]=b;p[b]=a;}}return {makekey(imask(first),omask(second),p),factor};}
DP diagrams(const rule::Poly&poly,int n){DP out;for(auto&[w,c]:poly)for(int input=0;input<(1<<n);input++){DP current{{identity(input),1}};for(auto it=w.rbegin();it!=w.rend();it++){DP next;for(auto[k,a]:current)for(auto[e,b]:elementary(omask(k),*it)){auto[z,f]=compose(k,e);dadd(next,z,I(a)*b*f);}current=move(next);if(current.empty())break;}for(auto[k,a]:current)dadd(out,k,I(a)*c);}return out;}
rule::Matrix expand_diagrams(const DP&d){rule::Matrix m;for(auto[k,c]:d){vector<pair<int,int>> pairs;for(int i=0;i<10;i++){int j=partner(k,i);if(j<10&&i<j)pairs.push_back({i,j});}int assignments=1;for(auto p:pairs)assignments*=3;for(int colors=0;colors<assignments;colors++){int z=colors,src=0,dst=0;for(auto[a,b]:pairs){int color=z%3+1;z/=3;for(int i:{a,b})if(i<5)src|=color<<(2*i);else dst|=color<<(2*(i-5));}uint32_t key=(src<<10)|dst;m[key]+=c;if(!m[key])m.erase(key);}}return m;}
map<uint32_t,rule::Matrix> reference_matrices(string dir,string fam){map<uint32_t,rule::Matrix> all;ifstream f(dir+"/rules_"+fam+".bin",ios::binary);assert(f);while(true){uint32_t sup;uint16_t src,dst;int32_t c;f.read((char*)&sup,4);if(!f)break;f.read((char*)&src,2);f.read((char*)&dst,2);f.read((char*)&c,4);assert(f);all[sup][(uint32_t(src)<<10)|dst]=c;}return all;}
struct BLocal{uint32_t support;vector<int>sites;array<vector<pair<Key,int64_t>>,32> rows;int64_t vacuum=0;};
struct BIndex{vector<BLocal>blocks;vector<Emb>embeddings;array<vector<int>,32>incidence;map<uint32_t,int64_t>vacpoly;array<vector<pair<uint32_t,int64_t>>,32>vacindex;int64_t constant=0;uint64_t rules=0;};
void geometry_add(BIndex&b,BLocal block){int bi=b.blocks.size(),n=block.sites.size();b.blocks.push_back(move(block));for(int t=0;t<32;t++){Emb e{};e.block=bi;for(int i=0;i<n;i++){e.sites[i]=rule::translate(b.blocks.back().sites[i],t);e.mask|=1u<<e.sites[i];}int ei=b.embeddings.size();b.embeddings.push_back(e);for(int i=0;i<n;i++)b.incidence[e.sites[i]].push_back(ei);if(b.blocks.back().vacuum)for(uint32_t sub=e.mask;;sub=(sub-1)&e.mask){b.vacpoly[sub]+=b.blocks.back().vacuum*(__builtin_popcount(sub)%2?-1:1);if(!sub)break;}}}
BIndex compile_brauer(string fam,string out,string reference){rule::canonicalize=true;rule::Stats st;auto motifs=rule::motifs(fam,st,true);auto expected=reference_matrices(reference,fam);BIndex result;ofstream bin(out+"/diagrams_"+fam+".bin",ios::binary);uint64_t compared=0,maxcoef=0;int stabilized=0;for(auto &[sup,p]:motifs){int n=__builtin_popcount(sup);int stabilizer=0;for(int t=0;t<32;t++){uint32_t shifted=0;for(int i=0;i<32;i++)if(sup>>i&1)shifted|=1u<<rule::translate(i,t);stabilizer+=shifted==sup;}if(stabilizer>1){assert(stabilizer==4);stabilized++;}auto d=diagrams(rule::localize(p,sup),n);auto matrix=expand_diagrams(d);assert(matrix==expected.at(sup));compared+=uint64_t(1)<<(4*n);BLocal b;b.support=sup;for(int i=0;i<32;i++)if(sup>>i&1)b.sites.push_back(i);for(auto[k,c]:d){bin.write((char*)&sup,4);bin.write((char*)&k,8);bin.write((char*)&c,8);result.rules++;all_compiled_rules++;maxcoef=max<uint64_t>(maxcoef,llabs(c));if(imask(k)==0&&omask(k)==0)b.vacuum+=c;else b.rows[omask(k)].push_back({k,c});}geometry_add(result,move(b));assert(all_compiled_rules*32+1048576<=16*1048576);ofstream cp(out+"/checkpoint.json");cp<<"{\"stage\":\"compile_"<<fam<<"\",\"supports_completed\":"<<result.blocks.size()<<",\"rules\":"<<result.rules<<",\"cpu_seconds\":"<<rule::cpu()<<"}";cp.close();rule::guard();}assert(expected.size()==result.blocks.size());assert(stabilized==1);for(auto[m,c]:result.vacpoly)if(c){if(m)result.vacindex[__builtin_ctz(m)].push_back({m,c});else result.constant=c;}ofstream meta(out+"/compiler_"+fam+".json");meta<<"{\"rules\":"<<result.rules<<",\"fourfold_stabilized_supports\":"<<stabilized<<",\"supports\":"<<result.blocks.size()<<",\"exact_local_matrix_entries_compared\":"<<compared<<",\"max_abs_diagram_coefficient\":"<<maxcoef<<",\"serialized_bytes\":"<<result.rules*20<<",\"conservative_rule_index_charge_bytes\":"<<result.rules*32+1048576<<"}";return result;}
// Small-graph full connected-tuple compiler, with no translation quotient.
void small_brauer(string dir){ofstream result(dir+"/small_validation.jsonl");for(int nx:{4,5}){physical::graph(nx,2);rule::graph(nx,2);physical::V vac{{0,1}},p2=physical::pairadd(vac,0,1),p4=physical::pairadd(p2,2,3),m6=physical::pairadd(p4,4,5),alt=physical::pairadd(physical::pairadd(physical::pairadd(vac,0,2),1,3),4,6);auto m=physical::sum(physical::scale(m6,-1),alt,2);for(string fam:{"N","F","L"}){rule::canonicalize=false;rule::Stats st;auto polys=rule::motifs(fam,st,false);vector<Block>blocks;for(auto&[sup,p]:polys){int n=__builtin_popcount(sup);auto mat=expand_diagrams(diagrams(rule::localize(p,sup),n));Block b;for(int i=0;i<physical::N;i++)if(sup>>i&1)b.sites.push_back(i);for(auto[key,c]:mat)b.columns[key>>10].push_back({uint16_t(key&1023),c});blocks.push_back(move(b));rule::guard();}auto got=apply_rules(blocks,m);auto expected=fam=="N"?physical::CE(m):fam=="F"?physical::EE(m):physical::L(m);assert(got==expected);probe_reconstruct(got);result<<"{\"nx\":"<<nx<<",\"family\":\""<<fam<<"\",\"full_vector_equal\":true,\"states\":"<<got.size()<<",\"cpu_seconds\":"<<rule::cpu()<<"}\n";result.flush();cerr<<"small "<<nx<<" "<<fam<<" PASS CPU "<<rule::cpu()<<endl;}}char *args[]={const_cast<char*>("fixture"),const_cast<char*>(dir.c_str())};physical::physical_main(2,args);}
// Load the saved Cartesian matrices into an independently color-indexed reference action.
Indexed load_cartesian(string reference,string fam){Indexed idx;auto matrices=reference_matrices(reference,fam);for(auto&[sup,mat]:matrices){Local b;b.support=sup;b.vacuum=0;for(int i=0;i<32;i++)if(sup>>i&1)b.sites.push_back(i);int n=b.sites.size();b.rows.resize(1<<(2*n));for(auto[key,c]:mat){int src=key>>10,dst=key&1023;if(!src&&!dst)b.vacuum=c;else b.rows[dst].push_back({uint16_t(src),int32_t(c)});}int bi=idx.blocks.size();idx.blocks.push_back(move(b));for(int t=0;t<32;t++){Emb e{};e.block=bi;for(int i=0;i<n;i++){e.sites[i]=rule::translate(idx.blocks.back().sites[i],t);e.mask|=1u<<e.sites[i];}int ei=idx.embeddings.size();idx.embeddings.push_back(e);for(int i=0;i<n;i++)idx.incidence[e.sites[i]].push_back(ei);if(idx.blocks.back().vacuum)for(uint32_t sub=e.mask;;sub=(sub-1)&e.mask){idx.vacuum_poly[sub]+=idx.blocks.back().vacuum*(__builtin_popcount(sub)%2?-1:1);if(!sub)break;}}}for(auto[m,c]:idx.vacuum_poly)if(c){if(m)idx.vacindex[__builtin_ctz(m)].push_back({m,c});else idx.constant=c;}return idx;}
struct BC{uint64_t incidence=0,embeds=0,diagram_hits=0,source_requests=0,active_diagrams=0,matching_hits=0;};
array<I,15> brauer_action(const BIndex&idx,const array<int,6>&sites,BC&count){uint32_t mask=0;array<int,32>targetpos;targetpos.fill(-1);for(int i=0;i<6;i++)mask|=1u<<sites[i],targetpos[sites[i]]=i;int64_t vac=idx.constant;for(int site:sites)for(auto[sub,c]:idx.vacindex[site])if((sub&mask)==sub)vac+=c;auto initial=source(mask);array<I,15>out{};for(int p=0;p<15;p++)out[p]=I(vac)*initial[p];for(int site:sites)for(int ei:idx.incidence[site]){count.incidence++;const auto&e=idx.embeddings[ei];if(__builtin_ctz(e.mask&mask)!=site)continue;count.embeds++;const auto&b=idx.blocks[e.block];int occupied=0;for(int i=0;i<(int)b.sites.size();i++)if(mask>>e.sites[i]&1)occupied|=1<<i;for(auto[k,c]:b.rows[occupied]){count.diagram_hits++;uint32_t smask=mask&~e.mask;for(int i=0;i<(int)b.sites.size();i++)if(imask(k)>>i&1)smask|=1u<<e.sites[i];assert(__builtin_popcount(smask)==6);auto amps=source(smask);count.source_requests++;if(all_of(amps.begin(),amps.end(),[](auto a){return a==0;}))continue;count.active_diagrams++;array<int,32>sourcepos;sourcepos.fill(-1);int n=0;for(int i=0;i<32;i++)if(smask>>i&1)sourcepos[i]=n++;DSU base;for(int i=0;i<6;i++)if(!(e.mask>>sites[i]&1))base.join(sourcepos[sites[i]],i+6);auto leg=[&](int a){return a<5?sourcepos[e.sites[a]]:targetpos[e.sites[a-5]]+6;};for(int a=0;a<10;a++){int z=partner(k,a);if(z<10&&a<z){assert(leg(a)>=0&&leg(z)>=0);base.join(leg(a),leg(z));}}for(int p=0;p<15;p++)if(amps[p]){count.matching_hits++;DSU u=base;for(int j=0;j<6;j+=2)u.join(pairs6[p][j],pairs6[p][j+1]);array<vector<int>,15>external;for(int j=0;j<6;j++)external[u.root(j+6)].push_back(j);int part[6];fill(part,part+6,-1);int factor=1;for(int j=0;j<12;j++)if(u.active[j]&&u.root(j)==j){assert(external[j].size()==0||external[j].size()==2);if(external[j].empty())factor*=3;else{int a=external[j][0],b=external[j][1];part[a]=b;part[b]=a;}}int q=-1;for(int j=0;j<15;j++){bool same=true;for(int z=0;z<6;z+=2)same&=part[pairs6[j][z]]==pairs6[j][z+1];if(same)q=j;}assert(q>=0);out[q]+=I(c)*factor*amps[p];}}}return out;}
int main(int argc,char**argv){assert(argc==3);string dir=argv[1],reference=argv[2];rule::outdir=dir;rule::deadline=55.;physical_edge();matching({0,1,2,3,4,5},{},0);probes();for(int n=0;n<=32;n++){chooseN[n][0]=1;for(int k=1;k<=6;k++)chooseN[n][k]=n?chooseN[n-1][k-1]+chooseN[n-1][k]:0;}ifstream g(dir+"/../geometry_8x4.txt");int nr,dd,ne;g>>nr>>dd>>ne;assert(nr==32&&dd==14);for(int j=0;j<ne;j++){int a,b,w;g>>a>>b>>w;adjmat[a][b]=adjmat[b][a]=w;}for(int a=0;a<32;a++)for(int b=a+1;b<32;b++)g>>orbit[a][b],orbit[b][a]=orbit[a][b];ifstream cf(dir+"/../reference_coefficients.txt");int64_t discard;for(int j=0;j<14;j++)cf>>discard;for(auto&c:cm)cf>>c;assert(g&&cf);ofstream report(dir+"/summary.json");report<<"{\"families\":[";bool first=true;try{small_brauer(dir);rule::graph(8,4);ofstream samples(dir+"/samples.jsonl");for(string fam:{"N","F","L"}){double began=rule::cpu();auto idx=compile_brauer(fam,dir,reference);double compilation=rule::cpu()-began;auto cart=load_cartesian(reference,fam);lazy.clear();lookups=misses=peakcache=0;double bc=0,cc=0;BC totals;int complete=0;for(int s=0;s<512;s++){if(rule::cpu()>52.)break;auto target=unrank(uint64_t(s)*169910/511);BC count;double t=rule::cpu();auto output=brauer_action(idx,target,count);double bseconds=rule::cpu()-t;Count refcount;t=rule::cpu();auto expected=indexed_action(cart,target,refcount);double cseconds=rule::cpu()-t;assert(output==expected);bc+=bseconds;cc+=cseconds;totals.diagram_hits+=count.diagram_hits;totals.matching_hits+=count.matching_hits;totals.source_requests+=count.source_requests;totals.active_diagrams+=count.active_diagrams;samples<<"{\"family\":\""<<fam<<"\",\"sample\":"<<s<<",\"diagram_hits\":"<<count.diagram_hits<<",\"active_diagrams\":"<<count.active_diagrams<<",\"matching_hits\":"<<count.matching_hits<<",\"source_requests\":"<<count.source_requests<<",\"brauer_cpu_seconds\":"<<bseconds<<",\"cartesian_cpu_seconds\":"<<cseconds<<",\"all_15_channels_equal\":true}\n";samples.flush();complete++;}if(!first)report<<",";first=false;report<<"{\"name\":\""<<fam<<"\",\"diagrams\":"<<idx.rules<<",\"compiler_cpu_seconds\":"<<compilation<<",\"samples\":"<<complete<<",\"brauer_cpu_seconds\":"<<bc<<",\"cartesian_reference_cpu_seconds\":"<<cc<<",\"diagram_hits\":"<<totals.diagram_hits<<",\"active_diagrams\":"<<totals.active_diagrams<<",\"matching_hits\":"<<totals.matching_hits<<",\"source_requests\":"<<totals.source_requests<<"}";report.flush();cerr<<fam<<" diagrams "<<idx.rules<<" samples "<<complete<<" CPU "<<rule::cpu()<<endl;rule::guard();if(complete!=512)break;}rusage r{};getrusage(RUSAGE_SELF,&r);report<<"],\"cpu_seconds\":"<<rule::cpu()<<",\"peak_rss_kib\":"<<r.ru_maxrss<<"}";return 0;}catch(string why){report<<"],\"incomplete\":true,\"reason\":\""<<why<<"\"}";return 2;}}
